<template><div class="module-stack"><PageState v-if="loading" type="loading" :title="`正在加载 ${title}`"/><template v-else-if="section==='overview'"><MetricStrip :items="metrics"/><div class="overview-grid"><section class="panel summary-card"><h2>{{title}}运行摘要</h2><p>{{description}}</p><dl class="fact-list"><div><dt>关联集群</dt><dd>{{related.length}}</dd></div><div><dt>实例 / Broker</dt><dd>{{nodeCount}}</dd></div><div><dt>部署正常</dt><dd>{{healthyCount}}</dd></div><div><dt>数据来源</dt><dd>Live + Mock</dd></div></dl></section><section class="panel summary-card"><h2>管理边界</h2><p>{{boundary}}</p><t-button theme="primary" @click="openList">查看集群列表</t-button></section></div></template><DataPanel v-else-if="section==='relations'" title="关联列表" :description="relationDescription" :data="relationRows" :columns="relationColumns"><template #name="{row}"><span class="identity-cell"><LinkIcon/><span><strong>{{row.name}}</strong><small>{{row.description}}</small></span></span></template><template #status="{row}"><StatusBadge :value="row.status"/></template><template #actions="{row}"><t-button variant="text" theme="primary" @click="openTopology(row)">查看拓扑</t-button></template></DataPanel><DataPanel v-else :title="`${title}列表`" :description="description" :data="listRows" :columns="listColumns"><template #name="{row}"><span class="identity-cell"><component :is="kind==='meta'?DataBaseIcon:ServerIcon"/><span><strong>{{row.name}}</strong><small>{{row.description}}</small></span></span></template><template #status="{row}"><StatusBadge :value="row.status??row.deployStatus"/></template><template #actions="{row}"><t-button variant="text" theme="primary" @click="openConsole(row)">管理</t-button><t-button variant="text" @click="openTopology(row)">拓扑</t-button></template></DataPanel></div></template>
<script setup lang="ts">
import { computed } from "vue"; import { useRouter } from "vue-router"; import { DataBaseIcon, LinkIcon, ServerIcon } from "tdesign-icons-vue-next"; import { mockComponentClusters } from "../../mock/mockClusterRelations"; import { useMockClusterStore } from "../../stores/mockCluster"; import MetricStrip from "../common/MetricStrip.vue"; import DataPanel from "../common/DataPanel.vue"; import StatusBadge from "../common/StatusBadge.vue"; import PageState from "../common/PageState.vue";
const props=defineProps<{kind:string;section:string;clusterId:string;live:any}>();const router=useRouter(),store=useMockClusterStore();const types=computed(()=>props.kind==="storage"?["kafka","rocketmq"]:[props.kind]);const title=computed(()=>props.kind==="runtime"?"Runtime 集群":props.kind==="meta"?"Meta 集群":"存储集群");const description=computed(()=>props.kind==="runtime"?"Runtime 负责消息接入与路由，实例在选定 Runtime 集群中管理。":props.kind==="meta"?"Meta 集群统一管理注册、发现与 Meta → EventMesh 主动关联。":"Kafka 与 RocketMQ 独立管理 Broker、物理 Topic 和消费组。");const boundary=computed(()=>props.kind==="meta"?"Meta 主动关联 EventMesh；关联写操作位于 Meta 集群控制台。":props.kind==="runtime"?"EventMesh 主动关联 Runtime；本模块展示集群和反向引用。":"EventMesh 主动关联存储；Kafka 使用 KRaft，RocketMQ 使用 NameServer 与 Broker Group。");
const loading=computed(()=>false);const relationIds=computed(()=>new Set(store.relations.filter((x:any)=>x.eventMeshClusterId===props.clusterId&&types.value.includes(x.componentType)).map((x:any)=>x.componentClusterId)));const mockRows=computed(()=>mockComponentClusters.filter((x:any)=>types.value.includes(x.type)));const liveRows=computed(()=>props.live?.data?.clusters??props.live?.data?.components??props.live?.data?.runtimes??props.live?.data??[]);const listRows=computed(()=>{const value=Array.isArray(liveRows.value)?liveRows.value:[];if(value.length)return value.map((x:any,i:number)=>({...x,id:x.id??i,status:x.status??x.deployStatus,description:x.description??`${title.value}资源`,nodeCount:x.nodes?.length??1,referenceCount:x.referenceCount??0}));return mockRows.value});const related=computed(()=>listRows.value.filter((x:any)=>relationIds.value.has(x.id)||x.currentAssociated===true));const nodeCount=computed(()=>related.value.reduce((n:number,x:any)=>n+(x.nodes?.length??x.nodeCount??1),0));const healthyCount=computed(()=>related.value.filter((x:any)=>/healthy|success/i.test(String(x.status??x.deployStatus))).length);const metrics=computed(()=>[{label:"关联集群",value:related.value.length,note:"当前 EventMesh"},{label:"实例 / Broker",value:nodeCount.value,note:"Live + Mock"},{label:"部署正常",value:healthyCount.value,note:"按部署状态"},{label:"反向引用",value:store.relations.filter((x:any)=>types.value.includes(x.componentType)).length,note:"多 EventMesh 共享"},{label:"健康探测",value:"—",note:"后端未接入"}]);
const listColumns=[{colKey:"name",title:"组件集群"},{colKey:"type",title:"类型"},{colKey:"status",title:"状态"},{colKey:"nodeCount",title:"实例 / Broker"},{colKey:"region",title:"地域"},{colKey:"version",title:"版本"},{colKey:"referenceCount",title:"关联 EventMesh"},{colKey:"actions",title:"操作",width:130}];const relationRows=computed(()=>mockRows.value.filter((x:any)=>relationIds.value.has(x.id)).map((x:any)=>({...x,direction:props.kind==="meta"?"Meta → EventMesh":`EventMesh → ${x.type}`})));const relationDescription=computed(()=>props.kind==="meta"?"方向：Meta 集群主动关联 EventMesh":"方向：EventMesh 主动关联组件集群；此处展示反向引用");const relationColumns=[{colKey:"name",title:"集群"},{colKey:"type",title:"类型"},{colKey:"direction",title:"关系方向"},{colKey:"region",title:"地域"},{colKey:"status",title:"状态"},{colKey:"actions",title:"操作"}];
function openList(){router.push({path:`/clusters/${encodeURIComponent(props.clusterId)}/${props.kind}`,query:{section:props.kind==="storage"?"kafka":"clusters"}})}function openConsole(row:any){if(["kafka","rocketmq"].includes(row.type))router.push(`/clusters/${encodeURIComponent(props.clusterId)}/storage/${row.type}/${encodeURIComponent(row.id)}/overview`);else router.push(`/clusters/${encodeURIComponent(props.clusterId)}/${props.kind}/${encodeURIComponent(row.id)}/overview`)}function openTopology(row:any){router.push({path:`/clusters/${encodeURIComponent(props.clusterId)}/topology`,query:{node:`component-${row.id}`}})}
</script>
